import { Component, OnInit, OnDestroy, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterModule } from '@angular/router';
import { HttpClient, HttpParams } from '@angular/common/http';

export interface Zone {
  id: number;
  name: string;
  status: 'available' | 'occupied' | 'maintenance' | 'closed';
  statusLabel: string;
  pseudo?: string;
}

export interface Client {
  clientId: number;
  numeroClient: string;
  nom: string;
  prenom: string;
  telephone: string;
  email: string;
  adresseInstallation: string;
}

export interface Reclamation {
  id: number;
  reference: string;
  statut: 'OUVERTE' | 'EN_COURS_IA' | 'RESOLUE_PAR_IA' | 'ESCALADEE_SUPPORT' | 'CLOTUREE';
  priorite: 'BASSE' | 'NORMALE' | 'HAUTE';
  description: string;
  categorieCode: string;
  categorieLibelle: string;
  sousCategorieCode: string;
  sousCategorieLibelle: string;
  dateCreation: string;
  dateMiseAJour: string;
}

export interface ReclamationItem {
  reclamation: Reclamation;
  client: Client;
}

export interface Page<T> {
  content: T[];
  totalElements: number;
  totalPages: number;
  size: number;
  number: number;
}



const API_URL = 'http://localhost:8080/api';

@Component({
  selector: 'app-zone',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterModule],
   templateUrl: './zone.component.html',
   styleUrls: ['./zone.component.css']
})

export class ZoneComponent implements OnInit{

private http = inject(HttpClient);
  private router = inject(Router);
  private readonly reclamationsUrl = `${API_URL}/reclamations`;

  // --- 1. GESTION DES 12 ZONES ---
  selectedFilter: 'all' | 'available' | 'occupied' | 'maintenance' | 'closed' = 'all';
  isModalOpen: boolean = false;
  selectedZone: Zone | null = null;
  newPseudo: string = '';
  enteredPassword: string = '';
  readonly REQUIRED_PASSWORD: string = 'hexabyte';
  errorMessage: string = '';

  zones: Zone[] = [
    { id: 1, name: 'Zone 1', status: 'available', statusLabel: 'Disponible' },
    { id: 2, name: 'Zone 2', status: 'occupied', statusLabel: 'Occupé', pseudo: 'Agent Karim' },
    { id: 3, name: 'Zone 3', status: 'maintenance', statusLabel: 'En maintenance' },
    { id: 4, name: 'Zone 4', status: 'available', statusLabel: 'Disponible' },
    { id: 5, name: 'Zone 5', status: 'closed', statusLabel: 'Fermé (Admin)' },
    { id: 6, name: 'Zone 6', status: 'occupied', statusLabel: 'Occupé', pseudo: 'Tech Sonia' },
    { id: 7, name: 'Zone 7', status: 'available', statusLabel: 'Disponible' },
    { id: 8, name: 'Zone 8', status: 'maintenance', statusLabel: 'En maintenance' },
    { id: 9, name: 'Zone 9', status: 'available', statusLabel: 'Disponible' },
    { id: 10, name: 'Zone 10', status: 'occupied', statusLabel: 'Occupé', pseudo: 'Admin Mehdi' },
    { id: 11, name: 'Zone 11', status: 'closed', statusLabel: 'Fermé (Admin)' },
    { id: 12, name: 'Zone 12', status: 'available', statusLabel: 'Disponible' }
  ];

  // --- 2. GESTION DES RECLAMATIONS & CLIENTS ---
  items: ReclamationItem[] = [];
  loading: boolean = false;
  reclamationSearch: string = '';
  selectedStatus: string = 'TOUS';

  // Modale Fiche Client
  isClientModalOpen: boolean = false;
  selectedClient: Client | null = null;
  selectedReclamationRef: string = '';

  // --- 3. HORLOGE 12H ---
  currentTimeFormatted: string = '';
  private clockInterval: any;

  ngOnInit(): void {
    this.updateClock();
    this.clockInterval = setInterval(() => this.updateClock(), 1000);
    this.chargerReclamations();
  }

  ngOnDestroy(): void {
    if (this.clockInterval) clearInterval(this.clockInterval);
  }

  private updateClock(): void {
    const now = new Date();
    let hours = now.getHours();
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12;
    this.currentTimeFormatted = `${String(hours).padStart(2, '0')}:${minutes}:${seconds} ${ampm}`;
  }

  // --- METHODES ZONES ---
  get filteredZones(): Zone[] {
    if (this.selectedFilter === 'all') return this.zones;
    return this.zones.filter(zone => zone.status === this.selectedFilter);
  }

  onZoneClick(zone: Zone): void {
    this.selectedZone = zone;
    this.newPseudo = zone.pseudo || '';
    this.enteredPassword = '';
    this.errorMessage = '';
    this.isModalOpen = true;
  }

  closeModal(): void {
    this.isModalOpen = false;
    this.selectedZone = null;
    this.errorMessage = '';
  }

  saveZoneProfile(): void {
    if (this.enteredPassword !== this.REQUIRED_PASSWORD) {
      this.errorMessage = "Mot de passe incorrect (Indice: hexabyte)";
      return;
    }

    if (this.selectedZone) {
      this.selectedZone.pseudo = this.newPseudo;
      if (this.newPseudo.trim() !== '') {
        this.selectedZone.status = 'occupied';
        this.selectedZone.statusLabel = 'Occupé';
      }
    }

    this.closeModal();
    this.router.navigate(['/admin/zone']);
  }

  // --- METHODES RECLAMATIONS ---
  chargerReclamations(): void {
    this.loading = true;
    const params = new HttpParams().set('page', 0).set('size', 10);

    this.http.get<Page<ReclamationItem>>(this.reclamationsUrl, { params }).subscribe({
      next: (data) => {
        this.items = data.content || [];
        this.loading = false;
      },
      error: (err) => {
        console.error('Erreur chargement réclamations', err);
        this.loading = false;
      }
    });
  }

  openClientDetails(client: Client, reclamationRef: string): void {
    this.selectedClient = client;
    this.selectedReclamationRef = reclamationRef;
    this.isClientModalOpen = true;
  }

  closeClientModal(): void {
    this.isClientModalOpen = false;
    this.selectedClient = null;
  }

  get filteredItems(): ReclamationItem[] {
    return this.items.filter(item => {
      const rec = item.reclamation;
      const cli = item.client;
      const search = this.reclamationSearch.toLowerCase();

      const matchesSearch = 
        rec.reference.toLowerCase().includes(search) ||
        cli.nom.toLowerCase().includes(search) ||
        cli.prenom.toLowerCase().includes(search) ||
        rec.sousCategorieLibelle.toLowerCase().includes(search);

      const matchesStatus = this.selectedStatus === 'TOUS' || rec.statut === this.selectedStatus;
      return matchesSearch && matchesStatus;
    });
  }
}
